// internal/restful/v2/search.go line 145-185
func (h *SearchHandler) Search(ctx context.Context, req *restful.SearchReq) (*restful.SearchResp, error) {
    // Parse groupParams without range validation
    groupParams := req.GroupParams
    if groupParams != nil {
        groupByField := groupParams.GroupByField
        groupSize := groupParams.GroupSize  // No range check: accepts 0, -1, any int
        // Direct pass-through to search executor without validation
        searchReq.GroupByField = groupByField
        searchReq.GroupSize = groupSize
    }
    // Execute search - executor handles edge cases internally
    return h.executor.Search(ctx, searchReq)
}
